 AND method='GET' AND path='/dns/{domain}' AND active AND price>=0 AND origin_override='https://dns.google' FOR UPDATE;
 IF NOT EXISTS (SELECT 1 FROM catalog.capability_execution_contracts WHERE endpoint_id=baseline.id
