   'security','lookup','https://developers.google.com/speed/public-dns/docs/doh/json',item->>'description',
   'provider_documentation_and_live_probe',1,'https://dns.google',item->>'name',true
  WHERE NOT EXISTS(SELECT 1 FROM providers.api_endpoints WHERE api_id=source_id AND method='GET' AND path=item->>'path');
  SELECT id INTO STRICT endpoint FROM providers.api_endpoints WHERE api_id=source_id AND method='GET' AND path=item->>'path';
  IF NOT EXISTS(SELECT 1 FROM providers.api_endpoints WHERE id=endpoint AND active AND price=baseline.price
   AND payment_required IS NOT DISTINCT FROM baseline.payment_required AND origin_override='https://dns.google'
   AND query_params=input_schema AND response_body=item->'schema' AND response_example=item->'sample' AND cache_ttl_seconds=0)
  THEN RAISE EXCEPTION 'typed DNS endpoint drift: %',cap; END IF;
  INSERT INTO catalog.capability_offers(capability_slug,endpoint_id,api_id,source,confidence,input_map,fixed_params,output_map,notes)
  VALUES(cap,endpoint,source_id,'curated',1,mapping,'{}',outputs,'One exact DNS name and record type; same tariff as existing MX lookup.')
  ON CONFLICT(capability_slug,endpoint_id) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM catalog.capability_offers WHERE capability_slug=cap AND endpoint_id=endpoint
   AND api_id=source_id AND input_map=mapping AND fixed_params='{}'::jsonb AND output_map=outputs)
  THEN RAISE EXCEPTION 'typed DNS offer drift: %',cap; END IF;
  INSERT INTO catalog.capability_execution_contracts(capability_slug,endpoint_id,version,status,requires,produces,input_map,
   fixed_params,output_map,cardinality,identifies,max_fan_out,preconditions,pagination,effect,price_model,freshness_seconds,
   sample_payload,validated_at,validated_note,notes,adapter_version)
  VALUES(cap,endpoint,1,'active',required_facts,produced,mapping,'{}',outputs,'one',NULL,1,'{}','{}','read','per_call',1,
   item->'sample',now(),'Google DNS JSON documentation, direct free response captures and Rust normalization tests, 2026-10-07.',
   'Deploy typed DNS adapter before this migration. Never infer company domain ownership.','domain-intelligence-v2')
  ON CONFLICT(capability_slug,endpoint_id,version) DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM catalog.capability_execution_contracts c WHERE c.capability_slug=cap AND c.endpoint_id=endpoint
   AND c.version=1 AND c.status='active' AND c.requires=required_facts AND c.produces=produced AND c.input_map=mapping
   AND c.fixed_params='{}'::jsonb AND c.output_map=outputs AND c.cardinality='one' AND c.identifies IS NULL
   AND c.max_fan_out=1 AND c.preconditions='{}'::jsonb AND c.pagination='{}'::jsonb AND c.effect='read' AND c.price_model='per_call'
   AND c.freshness_seconds=1 AND c.sample_payload=item->'sample' AND c.adapter_version='domain-intelligence-v2')
  THEN RAISE EXCEPTION 'typed DNS contract drift: %',cap; END IF;
 END LOOP;
END $migration$;
COMMIT;
